<script setup lang="ts">
import {uiLabel} from '../ui-label'
import {entryDisplayName as localizedEntryName} from '../runtime-presentation'

import { i18n as controlI18n } from '../../app/i18n'
const { t: controlText } = controlI18n.global

import MapFieldPicker from "../map-selection/MapFieldPicker.vue"
import {summonFormNames} from './labels'
import {MODE_NAMES} from '../../core/runtime'
import {computed,ref,watch} from 'vue'
import type {RoomView} from '../../online/protocol'
import type {SummonAction} from '../../persistence/summon-action-schema'
import M3DestinationPreview from '../m3/M3DestinationPreview.vue'
const props=defineProps<{view:RoomView;busy:boolean}>(),emit=defineEmits<{action:[SummonAction]}>()
const index=ref('0'),form=ref(''),materialId=ref(''),x=ref(6),y=ref(4),height=ref(0),note=ref(''),completed=ref(false),creatureType=ref<'celestial'|'fey'|'fiend'>('fey'),corpseIds=ref<string[]>([]),maintainIds=ref<string[]>([]),riderId=ref('')
const choices=computed(()=>props.view.summonChoices??[]),choice=computed(()=>choices.value[Number(index.value)]),scene=computed(()=>props.view.scene),source=computed(()=>scene.value?.tokens.find(t=>[t.id,t.characterId,t.npcId,t.actorId].includes(choice.value?.sourceId??''))),corpseRows=computed(()=>props.view.summonCorpses??[])
watch(()=>choice.value?[choice.value.sourceId,choice.value.key,choice.value.mode].join(':'):'',()=>{const c=choice.value;form.value=c?.forms[0]??'';materialId.value=c?.materials[0]?.id??'';completed.value=false;corpseIds.value=[];maintainIds.value=[]},{immediate:true})
const long=computed(()=>/minute|hour/i.test(choice.value?.castingTime??'')&&!choice.value?.key.startsWith('chain:')),span=computed(()=>['find-steed','phantom-steed'].includes(choice.value?.spellId??'')?2:1)
function submit(){const c=choice.value,s=scene.value;if(!c||!s)return;emit('action',{operation:'cast',sourceId:c.sourceId,key:c.key,mode:c.mode,form:form.value,position:{sceneId:s.id,x:x.value,y:y.value,span:span.value,spatial:{height:height.value,layer:source.value?.spatial?.layer??'material'}},materialId:materialId.value,receipt:crypto.randomUUID(),note:note.value,options:{creatureType:creatureType.value,riderId:riderId.value||undefined,castingCompleted:completed.value,corpseIds:corpseIds.value.length?corpseIds.value:undefined,maintainIds:maintainIds.value.length?maintainIds.value:undefined}})}
</script>
<template><details v-if="choices.length" class="summon-form"><summary>{{ controlText('resourceFlow.castSummoningSpell') }}</summary><div class="form-stack">
 <label>{{ controlText('remainingField.actualSourceAndCastingMethod') }}<select v-model="index"><option v-for="(c,n) in choices" :key="c.sourceId+c.key+c.mode" :value="String(n)">{{c.sourceName}} · {{localizedEntryName(c)}} · {{uiLabel(MODE_NAMES[c.mode])??(c.mode==='npc'?controlText('expressionFour.npcSActualAbility'):c.mode)}}</option></select></label>
 <div class="s-two"><label>{{ controlText('domain.form') }}<select v-model="form"><option v-for="f in choice?.forms" :key="f" :value="f">{{uiLabel(summonFormNames[f])??f}}</option></select></label><label v-if="choice?.spellId==='find-familiar'">{{ controlText('remainingField.spiritType') }}<select v-model="creatureType"><option value="celestial">{{ controlText('state.celestial') }}</option><option value="fey">{{ controlText('game.fey') }}</option><option value="fiend">{{ controlText('game.fiend') }}</option></select></label></div>
 <label v-if="choice?.spellId==='phantom-steed'">{{ controlText('remainingField.designatedRiderSelfByDefault') }}<MapFieldPicker kind="entity"><select v-model="riderId"><option value="">{{ controlText('resourceFlow.theCaster') }}</option><option v-for="t in scene?.tokens" :key="t.id" :value="t.characterId??t.npcId??t.actorId??t.id">{{localizedEntryName(t)}}</option></select></MapFieldPicker></label>
 <template v-if="choice?.spellId==='animate-dead'"><label>{{ controlText('remainingField.registeredRemainsToAnimateMultipleSelection') }}<select v-model="corpseIds" multiple><option v-for="r in corpseRows" :key="r.id" :value="r.id">{{localizedEntryName(r)}} · {{r.form}}</option></select></label><label>{{ controlText('remainingField.orRenewControlOfYourExistingUndead') }}<select v-model="maintainIds" multiple><option v-for="i in view.summons?.filter(i=>i.spellId==='animate-dead'&&i.sourceId===choice?.sourceId&&i.control==='controlled')" :key="i.id" :value="i.id">{{localizedEntryName(i)}} · {{i.controlEndsAt}}{{ controlText('game.hours') }}</option></select></label><p class="muted">{{ controlText('resourceFlow.creationAndControlRenewalCannotBeMixedEach') }}</p></template>
 <div class="s-three"><label>{{ controlText('game.landingX') }}<input v-model.number="x" type="number" min="0" :max="(scene?.grid.columns??80)-span" /></label><label>{{ controlText('game.landingY') }}<input v-model.number="y" type="number" min="0" :max="(scene?.grid.rows??80)-span" /></label><label>{{ controlText('game.height') }}<input v-model.number="height" type="number" /></label></div>
 <M3DestinationPreview :scene-id="scene?.id" :placement-span="span" :disabled="busy" @select="p=>{x=p.x;y=p.y;height=p.height}" v-if="source&&scene" :from="source" :to="{x,y,height}" :feet="scene.grid.feet" :columns="scene.grid.columns" :rows="scene.grid.rows" :walls="scene.walls" />
 <label v-if="choice?.material">{{ controlText('remainingField.registeredActualMaterials') }} {{localizedEntryName(choice.material)}}{{ controlText('remainingField.atLeast') }}{{choice.material.gp}}GP<select v-model="materialId"><option value="">{{ controlText('resourceFlow.chooseRegisteredMaterials') }}</option><option v-for="m in choice.materials" :key="m.id" :value="m.id">{{localizedEntryName(m)}}</option></select></label>
 <label v-if="long" class="inline"><input v-model="completed" type="checkbox" />{{ controlText('remainingField.requestGmVerificationOfContinuousCompletion') }} {{choice?.castingTime}}{{ controlText('remainingField.notASingleCombatAction') }}</label>
 <label>{{ controlText('remainingField.castingNotes') }}<input v-model="note" maxlength="1000" :placeholder="controlText('remainingField.describeFormMaterialsAndActualDestinationDoNot')" /></label>
 <button type="button" :disabled="busy||!note.trim()||!form||(!!choice?.material&&!materialId)||(long&&!completed)" @click="submit">{{view.self.role==='gm'?controlText('expressionFour.confirmActualCasting'):controlText('expressionFour.submitSummoningForReview')}}</button>
 </div></details></template>
<style scoped>.form-stack{display:grid;gap:.6rem;padding:.6rem 0}.form-stack label{display:grid;gap:.25rem;min-width:0}.form-stack .inline{display:flex;align-items:center}.form-stack input:not([type=checkbox]),.form-stack select{width:100%;min-width:0}.s-two,.s-three{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.s-three{grid-template-columns:repeat(3,minmax(0,1fr))}.summon-form p{font-size:.85rem;margin:0}@media(max-width:500px){.s-three{grid-template-columns:repeat(2,minmax(0,1fr))}.form-stack button{min-height:44px}}</style>
